def factorial(n):
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

print(factorial(4))

def sum_list(numbers):
    if not numbers:
        return 0
    return numbers[0] + sum_list(numbers[1:])

print(sum_list([1, 2, 3, 4]))

def power(base, exponent):
    if exponent == 0:
        return 1
    return base * power(base, exponent - 1)

print(power(7, 0))

def fibonacci(n):
    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

print(fibonacci(6))

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

factorial(4)

def find_max(numbers):
    if len(numbers) == 1:
        return numbers[0]
    rest = find_max(numbers[1:])
    return numbers[0] if numbers[0] > rest else rest

print(find_max([3, 7, 2, 9, 1]))

